<!-- Global Right-side Offcanvas Shell for Dynamic Content -->
<div class="offcanvas offcanvas-end" tabindex="-1" id="website-global-offcanvas" aria-labelledby="website-global-offcanvas-title" data-bs-backdrop="static" data-bs-keyboard="false" style="border-radius: 0 !important; outline: 0;">
    <header id="website-global-offcanvas-header" class="website-join__header" style="position: sticky; top: 0; z-index: 2; flex: 0 0 auto; background: var(--color-surface);">
        <div><span class="website-join__step">EATH TRAVEL PLANNER</span><h2 id="website-global-offcanvas-title" class="website-join__title">Plan your trek</h2><div id="website-global-offcanvas-subtitle" class="website-join__subtitle"></div></div>
        <button type="button" id="website-global-offcanvas-close" class="website-join__close" aria-label="Close side panel">&times;</button>
    </header>
    <div id="website-global-offcanvas-content" class="p-0 website-join__body" style="flex: 1 1 auto; overflow-y: auto; min-height: 0;"></div>
</div>
